-- Reviewed-by: Claude (agent, #47)
-- The automation engine (#47, ADR 0021): proposal, activity, automation_preference and
-- automation_threshold, tenant tables (tenantTable()) under FORCE RLS with ws_isolation
-- (tenantPolicy()). Grants come from the default privileges (app: 02-roles.sql, clerk: 0022).
--   * proposal.level and activity.level are CHECKed to L1..L4: a fifth level cannot be stored.
--   * capture_id, matter_id, proceeding_id and ai_call_id are plain uuids with no foreign key (the
--     capture table arrives with #43; an erase or an ai_call retention purge must not be blocked).
--   * activity.undo_expires_at is set by the engine to created_at + 7 days.
-- Expand only: new tables.
CREATE TABLE "proposal" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"capture_id" uuid,
	"kind" text NOT NULL,
	"level" text NOT NULL,
	"status" text DEFAULT 'proposed' NOT NULL,
	"payload" jsonb NOT NULL,
	"anchors" jsonb DEFAULT '[]'::jsonb NOT NULL,
	"confidence" numeric(4, 3),
	"matter_id" uuid,
	"proceeding_id" uuid,
	"idempotency_key" text NOT NULL,
	"needs_you" boolean DEFAULT false NOT NULL,
	"needs_you_reason" text,
	"entity_refs" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"meta" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"resolved_by" uuid,
	"resolved_at" timestamp with time zone,
	"resolution_reason" text,
	"edit_diff" jsonb,
	"ai_call_id" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"workspace_id" uuid NOT NULL,
	CONSTRAINT "proposal_workspace_id_id_uq" UNIQUE("workspace_id","id"),
	CONSTRAINT "proposal_level_chk" CHECK (level in ('L1', 'L2', 'L3', 'L4')),
	CONSTRAINT "proposal_status_chk" CHECK (status in ('proposed', 'accepted', 'edited', 'dismissed', 'expired', 'superseded')),
	CONSTRAINT "proposal_confidence_chk" CHECK (confidence is null or (confidence >= 0 and confidence <= 1)),
	CONSTRAINT "proposal_resolved_chk" CHECK (status in ('proposed', 'superseded') or resolved_at is not null)
);
